-- Apply once after backup. Prefer dotnet ef database update so EF records migration history.

CREATE TABLE IF NOT EXISTS voice_profiles (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "LearnerId" integer NOT NULL UNIQUE,
  "Goal" varchar(40) NOT NULL DEFAULT 'GENERAL',
  "Experience" varchar(30) NOT NULL DEFAULT 'BEGINNER',
  "Region" varchar(50),
  "MinutesPerDay" integer NOT NULL DEFAULT 20 CHECK ("MinutesPerDay" BETWEEN 5 AND 180),
  "UpdatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS voice_roadmaps (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "LearnerId" integer NOT NULL,
  "Version" integer NOT NULL,
  "SourcePracticeSessionId" integer,
  "Goal" varchar(40) NOT NULL DEFAULT 'GENERAL',
  "ModelVersion" varchar(50) NOT NULL DEFAULT '',
  "CreatedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UQ_voice_roadmaps_Learner_Version" UNIQUE ("LearnerId", "Version")
);
CREATE TABLE IF NOT EXISTS voice_skills (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "SkillCode" varchar(40) NOT NULL,
  "Name" varchar(120) NOT NULL,
  "Description" varchar(1000),
  "IsActive" boolean NOT NULL DEFAULT true,
  "DisplayOrder" integer NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_voice_skills_SkillCode" ON voice_skills ("SkillCode"